# Writes client/src/map_data.hpp from maps/vc.png and maps/lc.png. Run from the repository root:
#   perl tools/bin2hpp.pl > client/src/map_data.hpp

use strict;
use warnings;

print <<'EOF2';
#pragma once

// maps/vc.png and maps/lc.png (1024 x 1024), built from the original radar tiles by
// tools/radar2png.pl. Generated by tools/bin2hpp.pl, do not edit.

#include <cstdint>

namespace vc_lc::map_data {
EOF2

for my $name (qw(vc lc)) {
    open my $f, '<:raw', "maps/$name.png" or die "$name.png: $!";
    my @bytes = unpack('C*', do { local $/; <$f> });
    close $f;

    print "inline constexpr std::uint8_t ${name}_png[] = {\n";
    for (my $i = 0; $i < @bytes; $i += 16) {
        my $end = $i + 15 < $#bytes ? $i + 15 : $#bytes;
        print '    ', join(', ', map { sprintf('0x%02x', $_) } @bytes[$i .. $end]), ",\n";
    }
    print "};\n\n";
}
print "} // namespace vc_lc::map_data\n";
